package id.velioragardens.veliorasuite.module.fishing;
import id.velioragardens.veliorasuite.util.ColorUtil; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public final class FishingCommand implements CommandExecutor, TabCompleter { private final FishingManager manager; public FishingCommand(FishingManager manager){this.manager=manager;} @Override public boolean onCommand(CommandSender sender, Command command, String label, String[] args){ if(!(sender instanceof Player player)){sender.sendMessage("Command ini hanya player."); return true;} if(args.length==0){help(player); return true;} switch(args[0].toLowerCase(Locale.ROOT)){ case "top" -> manager.sendTop(player); case "stats" -> manager.sendStats(player); case "sell" -> manager.sellHand(player); case "reload" -> { if(!player.hasPermission("veliorasuite.fishing.admin")){player.sendMessage(ColorUtil.color("&cKamu tidak punya izin.")); return true;} manager.reload(); player.sendMessage(manager.msg("reload")); } default -> help(player);} return true;} private void help(Player p){p.sendMessage(ColorUtil.color("&8&m------------------------------")); p.sendMessage(ColorUtil.color("&aVelioraFishing")); p.sendMessage(ColorUtil.color("&e/vf top &7- Ranking pemancing")); p.sendMessage(ColorUtil.color("&e/vf stats &7- Statistik kamu")); p.sendMessage(ColorUtil.color("&e/vf sell &7- Jual ikan di tangan")); p.sendMessage(ColorUtil.color("&8&m------------------------------"));} @Override public List<String> onTabComplete(CommandSender sender, Command command, String alias, String[] args){ if(args.length==1)return filter(Arrays.asList("top","stats","sell","reload"),args[0]); return new ArrayList<>();} private List<String> filter(List<String>o,String i){List<String>r=new ArrayList<>();String l=i.toLowerCase(Locale.ROOT);for(String x:o)if(x.startsWith(l))r.add(x);return r;} }
